  await expect(mutate(db, principal, resource, { kind: 'create', operationId: randomUUID(), parent: comment, text: 'Reply to deleted root' })).rejects.toMatchObject({ code: 'CO_MANAGED_SHARED_WORK_FORBIDDEN' });
